tool_and_message_events.command:
/bin/bash -lc 'set -eu
review_dir=$(mktemp -d "$PWD/.desk-review.XXXXXXXX")
trap '"'python3 -c \"import shutil,sys; shutil.rmtree(sys.argv[1])\" \""'$review_dir"'"' EXIT
cp -R release \""'$review_dir/release"
cp vendor/hono-4.13.19.tgz "$review_dir/"
cd "$review_dir/release"
export npm_config_cache="$review_dir/npm-cache"
npm install --offline --ignore-scripts --no-audit --no-fund ../hono-4.13.19.tgz
npm ls hono --depth=0
npm test
node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import app from './app.mjs';

const cases = [
  {name: 'valid record', id: 'f2', shift: 'day', status: 200, body: {id: 'f2', title: 'North'}, steps: 'dispatch,session,read'},
  {name: 'missing session', id: 'f2', status: 401, body: {error: 'sign_in'}, steps: 'dispatch,session'},
  {name: 'missing record', id: 'missing-card', shift: 'day', status: 404, body: {error: 'not_found'}, steps: 'dispatch,session,read'},
  {name: 'supplied invalid record', id: 'r9', shift: 'day', status: 502, body: {error: 'invalid_record'}, steps: 'dispatch,session,read,error'},
];
let deviations = 0;
for (const {name, id, shift, status, body, steps} of cases) {
  const headers = shift ? {'x-shift': shift} : {};
  const request = new Request(new URL('/desk/' + id, 'http://localhost'), {method: 'GET', headers});
  let actual;
  try {
    const response = await app.request(request);
    assert.ok(response instanceof Response);
    actual = {status: response.status, body: await response.json(), steps: response.headers.get('x-desk-steps')};
    console.log(JSON.stringify({name, actual}));
    assert.deepStrictEqual(actual, {status, body, steps});
  } catch (error) {
    deviations++;
    console.log(JSON.stringify({name, expected: {status, body, steps}, error: error.message}));
  }
}
process.exitCode = deviations > 0 ? 1 : 0;
NODE"

